insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_music1_v1'
from (values
('117.208.c.1.A',1,'Sixth graders attend a live orchestra concert at the civic hall. They are experiencing an exemplary musical example through:','["a live performance", "a math drill", "a science lab", "a spelling test"]'::jsonb,0,'Live concerts and recordings expose students to models of fine playing.','original'),
('117.208.c.1.A',2,'A band director plays a professional recording of the piece students are learning so they can hear a model of:','["random notes", "good tone and style", "silent rests", "bad habits"]'::jsonb,1,'Exemplary recordings model quality performance.','original'),
('117.208.c.1.B',2,'The musical element that describes how high or low a sound is called:','["tempo", "texture", "pitch", "beat"]'::jsonb,2,'Pitch is highness or lowness of sound.','original'),
('117.208.c.1.B',2,'The family of instruments that includes the flute, clarinet and oboe is called:','["brass", "strings", "percussion", "woodwinds"]'::jsonb,3,'Flute, clarinet and oboe are woodwind instruments.','original'),
('117.208.c.1.C',2,'In 4/4 time, a whole note receives:','["four beats", "one beat", "three beats", "two beats"]'::jsonb,0,'A whole note lasts four beats in 4/4.','original'),
('117.208.c.1.C',2,'In 4/4 time, two quarter notes together equal one:','["sixteenth note", "half note", "whole note", "dotted whole note"]'::jsonb,1,'Two quarter notes equal one half note.','original'),
('117.208.c.1.D',2,'A piece with two main sections, A and B, is in:','["rondo form", "ternary form", "binary form", "theme and variations"]'::jsonb,2,'Binary form has two sections.','original'),
('117.208.c.1.D',2,'A piece that goes A, B, A is in:','["canon", "binary form", "free form", "ternary form"]'::jsonb,3,'Ternary form is ABA.','original'),
('117.208.c.1.E',2,'To prevent strain while playing an instrument, a student should:','["sit or stand with good posture", "tense the shoulders", "hold breath", "slump over"]'::jsonb,0,'Good posture protects the body.','original'),
('117.208.c.1.E',2,'Before a long rehearsal, singers protect their voices by:','["shouting", "drinking water and warming up gently", "whispering only", "skipping all rest"]'::jsonb,1,'Hydration and warm-ups support vocal health.','original'),
('117.208.c.2.A',2,'In music, a repeat sign tells the performer to:','["stop playing", "play louder", "play the section again", "play faster"]'::jsonb,2,'A repeat sign repeats a section.','original'),
('117.208.c.2.A',2,'The symbol ''f'' written under the staff means to play:','["slowly", "faster", "softly", "loudly"]'::jsonb,3,'Forte means loud.','original'),
('117.208.c.2.B',3,'A student writes a time signature at the beginning of her melody. She is notating:','["meter", "dynamics only", "timbre", "harmony"]'::jsonb,0,'The time signature shows the meter.','original'),
('117.208.c.2.B',3,'To write a rhythm in 3/4 meter, each measure needs a total of:','["six whole notes", "three quarter-note beats", "two quarter-note beats", "four quarter-note beats"]'::jsonb,1,'3/4 has three quarter-note beats per measure.','original'),
('117.208.c.2.C',3,'A student makes up a four-measure rhythm using quarter and eighth notes. She is:','["tuning", "transposing", "creating a rhythmic phrase", "conducting"]'::jsonb,2,'Composing a rhythm creates a phrase.','original'),
('117.208.c.2.C',3,'Creating a melodic phrase using only the notes C, D, E and G requires using:','["silence only", "unknown pitches", "random noise", "known pitches"]'::jsonb,3,'Phrases are built with known pitches.','original'),
('117.208.c.2.D',3,'Hearing a melody in your head while reading the notes silently is called:','["inner hearing", "strumming", "breathing", "tuning"]'::jsonb,0,'Inner hearing connects notation to sound.','original'),
('117.208.c.2.D',3,'Tapping the beat with the foot while reading music is a:','["lighting cue", "kinesthetic response", "visual aid", "written test"]'::jsonb,1,'Physical movement supports reading rhythm.','original'),
('117.208.c.2.E',3,'Sight reading means to:','["copy a recording", "memorize a long piece", "perform a piece you have not seen before", "compose a song"]'::jsonb,2,'Sight reading is performing unfamiliar music.','original'),
('117.208.c.2.E',3,'When sight reading, the first thing to check in the music is the:','["page number", "price", "composer''s birthday", "key signature and time signature"]'::jsonb,3,'Checking key and meter helps accuracy.','original'),
('117.208.c.3.A',2,'The unique quality of a sound that makes a flute sound different from a trumpet is called:','["timbre", "rest", "tempo", "key"]'::jsonb,0,'Timbre is tone color.','original'),
('117.208.c.3.A',3,'A choir blending their voices so no single voice sticks out is demonstrating:','["static", "characteristic vocal timbre together", "random volume", "silence"]'::jsonb,1,'Blend shows group timbre.','original'),
('117.208.c.3.B',3,'Good breath support when singing comes from:','["raising shoulders", "holding the chin high", "the diaphragm and lower ribs", "tightening the jaw"]'::jsonb,2,'Breath support uses the diaphragm.','original'),
('117.208.c.3.B',3,'A beginning band student holds the instrument with correct hand position to develop:','["fatigue", "bad habits", "tension", "fundamental technique"]'::jsonb,3,'Correct posture and hand position build technique.','original'),
('117.208.c.3.C',3,'Playing in tune with the rest of the ensemble is called accurate:','["intonation", "pitch bend", "rhythm", "tempo"]'::jsonb,0,'Intonation is playing in tune.','original'),
('117.208.c.3.C',3,'Playing a steady beat without rushing shows accurate:','["intonation", "rhythm", "timbre", "harmony"]'::jsonb,1,'Rhythmic accuracy keeps the beat steady.','original'),
('117.208.c.3.D',3,'A varied performance repertoire includes pieces from different:','["colors", "fonts", "styles and time periods", "prices"]'::jsonb,2,'Varied repertoire spans styles and eras.','original'),
('117.208.c.3.D',3,'Performing a folk song, a march and a hymn shows a:','["single style", "narrow list", "blank program", "varied repertoire"]'::jsonb,3,'Different types make repertoire varied.','original'),
('117.208.c.3.E',3,'A student sight-reads a new line at a steady tempo, even when she makes a mistake. She should:','["keep going and maintain the beat", "give up", "tear the page", "stop and restart"]'::jsonb,0,'Sight reading continues without stopping.','original'),
('117.208.c.3.E',3,'Before sight reading, a student scans for repeats, accidentals and:','["paper size", "rhythm patterns", "instrument price", "page color"]'::jsonb,1,'Scanning prepares for tricky spots.','original'),
('117.208.c.3.F',3,'A crescendo means to:','["gradually get softer", "play faster", "gradually get louder", "stop"]'::jsonb,2,'Crescendo is a gradual increase in volume.','original'),
('117.208.c.3.F',3,'The treble clef is also called the:','["F clef", "C clef", "B clef", "G clef"]'::jsonb,3,'The treble clef curls around G.','original'),
('117.208.c.3.G',3,'To create a melodic phrase that sounds finished, many composers end on the:','["tonic note", "silent rest", "highest note", "random note"]'::jsonb,0,'Ending on the tonic gives closure.','original'),
('117.208.c.3.G',3,'A student composes an eight-measure melody in the key of C. She is creating a:','["rhythmic round only", "melodic phrase", "tuning fork", "timbre chart"]'::jsonb,1,'Composing a melody creates a phrase.','original'),
('117.208.c.4.A',2,'Performing a corrido or a cowboy song connects to:','["space travel", "ocean life", "Texas heritage", "ancient Greece"]'::jsonb,2,'Texas heritage includes Tejano and cowboy music.','original'),
('117.208.c.4.A',3,'Learning a folk song from another country helps students appreciate:','["no cultures", "only one culture", "only modern music", "diverse cultures"]'::jsonb,3,'Music from different cultures broadens understanding.','original'),
('117.208.c.4.B',3,'Hearing a march, a lullaby and a dance, a student describes how each fits its:','["style and purpose", "color", "weight", "price"]'::jsonb,0,'Different styles serve different purposes.','original'),
('117.208.c.4.B',3,'Music written in the Baroque period often features:','["electric guitars", "ornamentation and steady rhythmic drive", "drum machines", "synthesizers"]'::jsonb,1,'Baroque style used ornaments and strong pulse.','original'),
('117.208.c.4.C',3,'Fractions in math relate to music because note values are:','["fractions of a key", "fractions of a bar line", "fractions of a whole note", "fractions of a clef"]'::jsonb,2,'Note values divide a whole note.','original'),
('117.208.c.4.C',3,'Sound waves studied in science relate to music because pitch depends on:','["the page number", "the price of the instrument", "the cover color", "the frequency of vibrations"]'::jsonb,3,'Frequency determines pitch.','original'),
('117.208.c.4.D',2,'A person who plays the trumpet in a professional symphony is a:','["career musician", "audience member", "stagehand only", "hobbyist"]'::jsonb,0,'Orchestral musicians have music careers.','original'),
('117.208.c.4.D',2,'Someone who plays piano at home for fun has a(n):','["legal job", "avocation in music", "exam", "vocation in music"]'::jsonb,1,'An avocation is a hobby.','original'),
('117.208.c.5.A',1,'A good audience member at a concert should:','["leave", "talk", "listen quietly and applaud at the right time", "text"]'::jsonb,2,'Concert etiquette respects the performers.','original'),
('117.208.c.5.A',2,'On stage, performers show good etiquette by:','["chewing gum", "running", "waving at friends", "entering and exiting quietly and bowing together"]'::jsonb,3,'Stage etiquette shows professionalism.','original'),
('117.208.c.5.B',3,'One criterion for evaluating a musical performance is:','["accuracy of rhythm and pitch", "the color of the stage", "the length of the program", "the seat softness"]'::jsonb,0,'Criteria relate to musical quality.','original'),
('117.208.c.5.B',3,'Listening to evaluate a choir''s blend means you listen for how well the voices:','["stay silent", "match and balance each other", "move on stage", "play loudly"]'::jsonb,1,'Blend and balance are evaluation criteria.','original'),
('117.208.c.5.C',3,'A student records her practice and listens to find mistakes. This is a tool for:','["advertising", "budgeting", "self-evaluation", "traveling"]'::jsonb,2,'Recording helps self-evaluation.','original'),
('117.208.c.5.C',3,'A practice log with goals helps a student improve by:','["wasting time", "hiding mistakes", "avoiding practice", "tracking progress toward goals"]'::jsonb,3,'Logs track personal improvement.','original'),
('117.208.c.5.D',4,'Comparing a student performance with an excellent recording of the same piece helps evaluate:','["quality and effectiveness", "stage size", "program covers", "ticket sales"]'::jsonb,0,'Exemplars give a model for evaluation.','original'),
('117.208.c.5.D',4,'A student says the ensemble''s tempo dragged compared to a model recording. She is:','["ignoring the performance", "evaluating a performance against an example", "sleeping", "guessing"]'::jsonb,1,'Evaluation compares to a model.','original'),
('117.208.c.5.E',3,'Conducting patterns and moving to the beat are examples of:','["spelling words", "science labs", "kinesthetic responses to music", "math facts"]'::jsonb,2,'Physical response shows musical understanding.','original'),
('117.208.c.5.E',3,'A student closes her eyes and sways with a slow lullaby, showing an appropriate response to its:','["ink", "price", "size", "mood and tempo"]'::jsonb,3,'Responses fit the music''s character.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
